{
  "candidate_edge_types": [
    {
      "name": "INVESTIGATES_FAILURE_CAUSE",
      "definition": "A subsequent agent action examines diagnostic information to determine the cause of a previously observed test failure or mismatch.",
      "source_description": "An execution event that produces a test failure or unexpected mismatch observation.",
      "target_description": "An event where the agent performs diagnostic actions to identify the cause of the failure."
    },
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action modifies the implementation in an attempt to resolve a failure identified during an earlier diagnostic step.",
      "source_description": "An event containing diagnosis or analysis that identifies the cause of a failure.",
      "target_description": "An event where the agent modifies code or configuration to fix the identified cause."
    },
    {
      "name": "VERIFIES_REPAIR",
      "definition": "A subsequent agent action runs tests or checks to determine whether a prior repair resolved the failure.",
      "source_description": "An event where the agent applies a code modification intended to fix a failure.",
      "target_description": "An event where the agent runs a test suite to verify the fix."
    },
    {
      "name": "EXTENDS_VERIFICATION",
      "definition": "After a verification test suite passes, the agent runs additional edge-case tests to further validate correctness.",
      "source_description": "An event where a verification test suite yields all-pass results.",
      "target_description": "An event where the agent runs additional tests targeting edge cases or boundary conditions."
    }
  ]
}

